import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Configuration (gflags)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md","lastUpdated":1790931789000}'),o={name:"guide/configuration.md"};function d(n,e,l,r,c,h){return s(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="configuration-gflags" tabindex="-1">Configuration (gflags) <a class="header-anchor" href="#configuration-gflags" aria-label="Permalink to &quot;Configuration (gflags)&quot;">​</a></h1><p>NeoFlux uses <a href="https://github.com/gflags/gflags" target="_blank" rel="noreferrer">gflags</a> for runtime configuration and <a href="https://github.com/google/glog" target="_blank" rel="noreferrer">glog</a> for logging. Every flag below is optional and passed on the command line:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\build\\bin\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">neoflux_app.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">render_backend</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">target_fps</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">120</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logtostderr</span></span></code></pre></div><h2 id="full-flag-reference" tabindex="-1">Full flag reference <a class="header-anchor" href="#full-flag-reference" aria-label="Permalink to &quot;Full flag reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>Type</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--render_backend</code></td><td><code>string</code></td><td><code>&quot;gl&quot;</code></td><td>Selects the tgfx render backend. Only <code>gl</code> is available in this build; <code>vulkan</code>, <code>cpu</code>, and any unknown value are a hard startup error (no silent fallback).</td></tr><tr><td><code>--target_fps</code></td><td><code>int32</code></td><td><code>60</code> (from <code>config::kDefaultTargetFps</code>)</td><td>Target frames-per-second for the application event loop.</td></tr><tr><td><code>--render_queue_capacity</code></td><td><code>uint64</code></td><td><code>2048</code> (from <code>config::kDefaultRenderQueueCapacity</code>)</td><td>Capacity of the SPSC render-command ring queue. Rounded up to a power of two (<code>std::bit_ceil</code>); one slot is reserved, so usable commands = <code>capacity - 1</code>.</td></tr><tr><td><code>--render_queue_drop_log_max</code></td><td><code>int32</code></td><td><code>10</code></td><td>Maximum number of &quot;render command queue full, dropped commands&quot; warnings emitted per process. After this many drops, subsequent overflows are counted silently. Raise this only when diagnosing back-pressure.</td></tr><tr><td><code>--verbose_logging</code></td><td><code>bool</code></td><td><code>false</code></td><td>Enables <code>VLOG(1)</code> output and mirrors INFO logs to stderr.</td></tr><tr><td><code>--logtostderr</code></td><td><code>bool</code></td><td><code>false</code></td><td>When set, writes all logs to stderr instead of files.</td></tr><tr><td><code>--log_dir</code></td><td><code>string</code></td><td><code>&quot;./logs&quot;</code></td><td>Directory for <code>.log</code> files (created automatically). Only used when <code>--logtostderr</code> is off.</td></tr><tr><td><code>--media_source</code></td><td><code>string</code></td><td><code>&quot;./assets/media/sample.mp4&quot;</code></td><td>Path or URL for the demo <code>MediaWidget</code> on the <code>/media</code> route.</td></tr></tbody></table><h3 id="render-backend" tabindex="-1"><code>--render_backend</code> <a class="header-anchor" href="#render-backend" aria-label="Permalink to &quot;`--render_backend`&quot;">​</a></h3><p>Defined in <code>neoflux/src/renderers/render_layer.cpp</code>. The default is <code>&quot;gl&quot;</code>. There is <strong>no silent fallback</strong>: requesting an unavailable backend is a hard startup failure — <code>RenderLayer::Start()</code> logs an error and returns <code>false</code>, so the application refuses to launch rather than quietly rendering through the wrong backend.</p><table tabindex="0"><thead><tr><th>Value</th><th>Behavior</th></tr></thead><tbody><tr><td><code>gl</code> (default)</td><td>The working desktop path: tgfx OpenGL on WGL, driven through the GLFW bridge.</td></tr><tr><td><code>vulkan</code></td><td>Refused unless tgfx was built with <code>TGFX_USE_VULKAN=ON</code> AND the host has a Vulkan device/driver. In a GL-only build this is a hard startup error.</td></tr><tr><td><code>cpu</code></td><td>Refused. tgfx has no software rasterizer, so there is no CPU backend to fall back to.</td></tr><tr><td>anything else</td><td>Refused as unknown.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>On today&#39;s desktop builds only <code>gl</code> exists. Pass it explicitly (<code>--render_backend=gl</code>) to make the intent clear; do not assume the other values silently work.</p></div><h3 id="target-fps" tabindex="-1"><code>--target_fps</code> <a class="header-anchor" href="#target-fps" aria-label="Permalink to &quot;`--target_fps`&quot;">​</a></h3><p>Sets <code>EventLoop::SetTargetFps()</code>. The loop sleeps between frames to respect the cap; input events and <code>MarkFrameDirty()</code> wake it early. Default <code>60</code>.</p><h3 id="render-queue-capacity" tabindex="-1"><code>--render_queue_capacity</code> <a class="header-anchor" href="#render-queue-capacity" aria-label="Permalink to &quot;`--render_queue_capacity`&quot;">​</a></h3><p>Configures the <code>SpscRingQueue&lt;RenderCommand&gt;</code> constructed by <code>RenderLayer</code>. The requested value is rounded up to the next power of two internally (<code>std::bit_ceil</code>) so index wrapping can use a bitwise AND. Because one slot is reserved to distinguish full from empty, a requested <code>2048</code> holds at most <code>2047</code> in-flight commands. If the producer catches up to the consumer, excess commands for that frame are dropped (rate-limited warning).</p><div class="warning custom-block"><p class="custom-block-title">Raise this only if you see &quot;render command queue full&quot; warnings</p><p>A larger queue costs memory and can add present latency. The default <code>2048</code> is plenty for typical widget trees.</p></div><h3 id="render-queue-drop-log-max" tabindex="-1"><code>--render_queue_drop_log_max</code> <a class="header-anchor" href="#render-queue-drop-log-max" aria-label="Permalink to &quot;`--render_queue_drop_log_max`&quot;">​</a></h3><p>When the render command queue is full and commands are being dropped, NeoFlux emits a <code>WARNING</code> log. To avoid flooding the log under sustained backpressure, only the first <code>N</code> drop warnings per process are printed; later drops are counted silently. Default <code>10</code>. Set to <code>0</code> to silence drop warnings entirely.</p><h3 id="media-source" tabindex="-1"><code>--media_source</code> <a class="header-anchor" href="#media-source" aria-label="Permalink to &quot;`--media_source`&quot;">​</a></h3><p>Path or URL passed to the built-in demo <code>MediaWidget</code> on the <code>/media</code> route. Default <code>./assets/media/sample.mp4</code>. This flag exists solely so the quick-start app can point at a test video without rebuilding; real applications construct their own <code>MediaWidget</code> and call <code>SetSource()</code> directly. If the path does not exist on disk (and is not a URL like <code>http://</code>/<code>rtsp://</code>), NeoFlux logs a WARNING at startup.</p><h3 id="verbose-logging" tabindex="-1"><code>--verbose_logging</code> <a class="header-anchor" href="#verbose-logging" aria-label="Permalink to &quot;`--verbose_logging`&quot;">​</a></h3><p>A convenience bool. When set, NeoFlux turns on <code>VLOG(1)</code> (<code>FLAGS_v = 1</code>) and mirrors INFO-level logs to stderr. This is the switch that makes the per-frame layout dump (<code>VLOG(1) &lt;&lt; widgetname [x y w h]</code>) appear.</p><h3 id="logtostderr" tabindex="-1"><code>--logtostderr</code> <a class="header-anchor" href="#logtostderr" aria-label="Permalink to &quot;`--logtostderr`&quot;">​</a></h3><p>This is a glog built-in flag. When glog is built without gflags integration, NeoFlux pre-scans <code>argv</code> for <code>--logtostderr</code> / <code>--nologtostderr</code> (and the <code>-</code> short forms) before gflags parses the rest. By default it is off and logs go to files.</p><h3 id="log-dir" tabindex="-1"><code>--log_dir</code> <a class="header-anchor" href="#log-dir" aria-label="Permalink to &quot;`--log_dir`&quot;">​</a></h3><p>Also a glog built-in flag, handled by the same argv pre-scan. Accepts both <code>--log_dir=PATH</code> and <code>--log_dir PATH</code>. When logging to files, it defaults to <code>./logs</code>, creates the directory if needed, and appends the <code>.log</code> extension. If the directory cannot be created, logging silently falls back to stderr.</p><h2 id="logging-in-code" tabindex="-1">Logging in code <a class="header-anchor" href="#logging-in-code" aria-label="Permalink to &quot;Logging in code&quot;">​</a></h2><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;glog/logging.h&gt;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LOG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(INFO) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Application started&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LOG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(WARNING) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Font not found, using default&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LOG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ERROR) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Rendering failed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">VLOG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Detailed per-frame debug info&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // shown with --verbose_logging</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Recommended development invocation</p><p>Because the app is built as a GUI-subsystem binary with no console, run with:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\build\\bin\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">neoflux_app.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logtostderr </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">verbose_logging</span></span></code></pre></div></div><h2 id="full-example" tabindex="-1">Full example <a class="header-anchor" href="#full-example" aria-label="Permalink to &quot;Full example&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\build\\bin\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">neoflux_app.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> `</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">target_fps</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">144</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> `</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">render_backend</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">`</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">render_queue_capacity</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4096</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> `</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logtostderr </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">`</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">verbose_logging</span></span></code></pre></div><p>This targets 144 FPS, uses the GL backend, enlarges the command queue to 4096, and streams verbose logs to the terminal.</p><h2 id="compile-time-constants-core-config-h" tabindex="-1">Compile-time constants (<code>core/config.h</code>) <a class="header-anchor" href="#compile-time-constants-core-config-h" aria-label="Permalink to &quot;Compile-time constants (`core/config.h`)&quot;">​</a></h2><p>Some values are <strong>compile-time</strong> (baked into the binary, not runtime flags). They live in <code>neoflux/include/neoflux/core/config.h</code> as <code>inline constexpr</code>:</p><table tabindex="0"><thead><tr><th>Constant</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>config::kCacheLineSize</code></td><td><code>64</code></td><td>Cache line size in bytes. Used to pad SPSC queue head/tail to separate cache lines (prevents false sharing). Override with <code>-DNEOFLUX_CACHE_LINE_SIZE=128</code> for Apple M-series / newer AMD.</td></tr><tr><td><code>config::kDefaultRenderQueueCapacity</code></td><td><code>2048</code></td><td>Default for <code>--render_queue_capacity</code>.</td></tr><tr><td><code>config::kDefaultTargetFps</code></td><td><code>60</code></td><td>Default for <code>--target_fps</code>.</td></tr><tr><td><code>config::kLongPressThresholdMs</code></td><td><code>500</code></td><td>Long-press detection threshold for <code>Button</code> (ms).</td></tr><tr><td><code>config::kFlingStopThreshold</code></td><td><code>0.02</code></td><td>Minimum fling velocity (screen heights/sec) below which inertia stops.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">gflag defaults follow config.h</p><p>The gflag definitions use these constants as their defaults. Change <code>kDefaultTargetFps</code> in <code>config.h</code> to <code>30</code>, rebuild, and <code>--target_fps</code> now defaults to <code>30</code> without touching the flag definition.</p></div>',34)])])}const u=t(o,[["render",d]]);export{g as __pageData,u as default};
